import{_ as e,c as o,o as a,b2 as i}from"./chunks/framework.CUhoHPxN.js";const k=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/introduction.md","filePath":"docs/guide/introduction.md"}'),d={name:"docs/guide/introduction.md"};function r(l,t,n,c,s,h){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor vp-link" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>QuickBoot（本仓库 <code>quickboot2</code>）是一套 <strong>企业后台全栈解决方案</strong>：Java 后端 + Vue 3 管理端 + VitePress 文档站，强调公共能力下沉、规范驱动协作与统一的前端列表/表单体验。</p><h2 id="仓库结构" tabindex="-1">仓库结构 <a class="header-anchor vp-link" href="#仓库结构" aria-label="Permalink to &quot;仓库结构&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>目录</th><th>说明</th></tr></thead><tbody><tr><td><code>quickboot/</code></td><td>Spring Boot 3 后端（Maven 多模块）</td></tr><tr><td><code>quick-ui/</code></td><td>Vue 3 + Vite + Element Plus 管理端</td></tr><tr><td><code>docs/</code></td><td>VitePress 文档站点（当前站点）</td></tr><tr><td><code>openspec/</code></td><td>OpenSpec 变更与规范</td></tr><tr><td><code>sdd/</code></td><td>前后端/数据库协作规范</td></tr></tbody></table></div><h2 id="技术栈一览" tabindex="-1">技术栈一览 <a class="header-anchor vp-link" href="#技术栈一览" aria-label="Permalink to &quot;技术栈一览&quot;">​</a></h2><h3 id="后端-quickboot" tabindex="-1">后端（quickboot） <a class="header-anchor vp-link" href="#后端-quickboot" aria-label="Permalink to &quot;后端（quickboot）&quot;">​</a></h3><ul><li>Java 17、Spring Boot 3.5.x</li><li>MyBatis-Plus、Flyway、Druid</li><li><strong>Sa-Token</strong>（会话 + OAuth2 授权服务器/客户端）</li><li>EasyExcel、Quartz、SpringDoc OpenAPI</li><li>缓存：Caffeine / Redis 可切换；配置加密：Jasypt</li></ul><h3 id="前端-quick-ui" tabindex="-1">前端（quick-ui） <a class="header-anchor vp-link" href="#前端-quick-ui" aria-label="Permalink to &quot;前端（quick-ui）&quot;">​</a></h3><ul><li>Vue 3.5、Vite 5、Pinia、Vue Router 4</li><li>Element Plus 2.x、Axios、Vitest</li><li><strong>C7 组件库</strong>（<code>src/packages</code>）：JSON 驱动表格/表单、Excel、字典标签等</li><li>包管理：<strong>pnpm 9</strong></li></ul><h2 id="quickboot-核心能力摘要" tabindex="-1">quickboot 核心能力摘要 <a class="header-anchor vp-link" href="#quickboot-核心能力摘要" aria-label="Permalink to &quot;quickboot 核心能力摘要&quot;">​</a></h2><h3 id="模块划分" tabindex="-1">模块划分 <a class="header-anchor vp-link" href="#模块划分" aria-label="Permalink to &quot;模块划分&quot;">​</a></h3><ul><li><strong>quickboot-common</strong>：统一响应 <code>R</code>、异常、校验分组、i18n、缓存、Excel、脱敏、验证码、文件存储、操作日志 AOP、Web 防火墙（XSS/SQL 注入/敏感词/幂等/CORS/安全头等）</li><li><strong>quickboot-core</strong>：预留模块（当前无业务 Java 代码）</li><li><strong>quickboot-web</strong>：启动入口、全部 Controller/Service/Mapper、Flyway 脚本</li></ul><h3 id="业务域" tabindex="-1">业务域 <a class="header-anchor vp-link" href="#业务域" aria-label="Permalink to &quot;业务域&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>域</th><th>能力</th></tr></thead><tbody><tr><td><strong>认证</strong></td><td>登录/登出、<code>getInfo</code>、<code>getRouters</code>、验证码、二维码</td></tr><tr><td><strong>系统管理</strong></td><td>用户、角色、菜单、部门、字典、参数、公告</td></tr><tr><td><strong>OAuth2</strong></td><td>授权服务器（AS）、第三方 IdP 联邦登录、Open API、客户端/提供方管理、Client HMAC 签名校验</td></tr><tr><td><strong>监控</strong></td><td>操作日志、登录日志、在线用户、定时任务及任务日志</td></tr><tr><td><strong>工具</strong></td><td>代码生成（表导入、预览、ZIP 下载）</td></tr></tbody></table></div><p>默认端口 <strong>9992</strong>；开发 Profile 使用 <strong>H2 文件库</strong>，生产使用 <strong>MySQL + Redis Token</strong>。</p><p>详见 <a href="./../backend/index.html" class="vp-link">后端概述</a>、<a href="./../backend/modules/index.html" class="vp-link">功能模块总览</a>。</p><h2 id="quick-ui-核心能力摘要" tabindex="-1">quick-ui 核心能力摘要 <a class="header-anchor vp-link" href="#quick-ui-核心能力摘要" aria-label="Permalink to &quot;quick-ui 核心能力摘要&quot;">​</a></h2><h3 id="架构特点" tabindex="-1">架构特点 <a class="header-anchor vp-link" href="#架构特点" aria-label="Permalink to &quot;架构特点&quot;">​</a></h3><ul><li><strong>动态路由</strong>：登录后调用 <code>/getRouters</code>，按菜单权限 <code>addRoute</code></li><li><strong>权限</strong>：<code>v-hasPermi</code> / <code>v-hasRole</code>、全局 <code>$auth</code></li><li><strong>请求</strong>：Bearer Token + <strong>Client HMAC 签名</strong>（与 <code>sys_oauth_client</code> 配套，见 OAuth2 文档）</li><li><strong>列表范式</strong>：业务列表优先 <strong>C7JsonTable</strong> + 列配置，样式对齐 <code>views/system/config/index.vue</code></li></ul><h3 id="业务页面" tabindex="-1">业务页面 <a class="header-anchor vp-link" href="#业务页面" aria-label="Permalink to &quot;业务页面&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>模块</th><th>页面</th></tr></thead><tbody><tr><td>系统</td><td>用户、角色、部门、菜单、字典、参数、公告、OAuth 客户端/提供方</td></tr><tr><td>监控</td><td>在线用户、操作日志、登录日志、定时任务、调度日志</td></tr><tr><td>工具</td><td>代码生成</td></tr><tr><td>OAuth</td><td>授权确认页 <code>oauth/authorize</code>；登录页第三方 IdP 入口</td></tr><tr><td>开发</td><td><code>dev/*</code> 下 C7 组件 E2E 演示页</td></tr></tbody></table></div><p>详见 <a href="./../frontend/index.html" class="vp-link">前端概述</a>、<a href="./../frontend/modules/index.html" class="vp-link">业务页面总览</a>。</p><h2 id="文档与规范" tabindex="-1">文档与规范 <a class="header-anchor vp-link" href="#文档与规范" aria-label="Permalink to &quot;文档与规范&quot;">​</a></h2><ul><li><a href="./capabilities-outline.html" class="vp-link">能力文档大纲</a>：全站目录与填充进度</li><li><a href="./quick-start.html" class="vp-link">快速上手</a>：本地运行三步</li><li>编码规范：仓库根 <code>AGENTS.md</code>、<code>sdd/*.md</code>、<code>DESIGN.md</code>（前端视觉）</li><li>变更流程：<code>openspec/changes/&lt;change-id&gt;/</code></li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor vp-link" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>本地运行 → <a href="./quick-start.html" class="vp-link">快速上手</a></li><li>后端细节 → <a href="./../backend/index.html" class="vp-link">后端概述</a></li><li>前端细节 → <a href="./../frontend/index.html" class="vp-link">前端概述</a></li><li>OAuth2 对接 → <a href="./../backend/modules/oauth2.html" class="vp-link">OAuth2 集成</a></li></ul>',26)])])}const b=e(d,[["render",r]]);export{k as __pageData,b as default};
